$('"'[data-edit=\"0\"]').click();assert.equal(step(),0);assert.equal("'$('"'#first-name').value,'Jamie');submit();submit();assert.equal(step(),2);assert.equal("'$('"'.slot').getAttribute('aria-pressed'),'true');submit();submit();assert.equal("'$('"'#success').hidden,false);assert.equal("'$('"'#booking-form').hidden,true);assert.match("'$('"'#confirmation-detail').textContent,/NT-/);
"'$('"'#book-again').click();assert.equal(step(),0);assert.equal("'$('"'#first-name').value,'');assert.equal("'$('"'#summary-price').textContent,'120');assert.equal("'$('"'#success').hidden,true);
for(let i=0;i<10;i++) "'$('"'[data-counter=\"bedrooms\"][data-change=\"-1\"]').click();assert.equal("'$('"'#bedrooms-value').textContent,'0');assert.equal("'$('"'[data-counter=\"bedrooms\"][data-change=\"-1\"]').disabled,true);
for(let i=0;i<10;i++) "'$('"'[data-counter=\"bathrooms\"][data-change=\"1\"]').click();assert.equal("'$('"'#bathrooms-value').textContent,'6');assert.equal("'$('"'[data-counter=\"bathrooms\"][data-change=\"1\"]').disabled,true);
